"""Prepare literal Selection parent source only; no candidate or actual pass claim."""
from pathlib import Path
import json

r = Path(__file__).resolve().parents[2]
out = r / 'artifacts/replica/windows-download'
lines = (r / 'docs/replica/source/original.js').read_text().splitlines()
prefixes = ('const initial=', 'let state=', 'const esc=', 'const icons=', 'const icon=',
            'const t=', 'const btn=', 'const pill=', 'const notice=', 'const heading=',
            'const categoryDefs=', 'function select(', 'function footer(',
            'function trialPreparation(', 'function filteredTables(',
            'function tableCountLabel(', 'function tableRows(', 'function syncTableSelection(')
literal = '\n'.join(line for line in lines if line.startswith(prefixes))
variants = ['expanded', 'trial-unready', 'trial-ready', 'no-categories', 'no-tables',
            'access-only-no-tables', 'partial-tables', 'query-orders', 'query-none', 'manual-target-query']
cases = [{'id': f'{lang}-{width}-default', 'language': lang, 'viewport': width, 'state': 'default'}
         for lang in ['ko', 'en'] for width in [960, 1100, 1101, 1180, 1181, 1280, 1440, 1600]]
cases += [{'id': f'{lang}-1180-{variant}', 'language': lang, 'viewport': 1180, 'state': variant}
          for lang in ['ko', 'en'] for variant in variants]
script = r'''function recordError(e){fetch('/evidence/preflight-selectionpage-'+(new URLSearchParams(parent.location.search).get('os')==='windows'?'windows':'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({diagnostic:true,id:new URLSearchParams(location.search).get('id'),error:String(e.message||e.reason||e),stack:e.error?.stack||e.reason?.stack})})}addEventListener('error',recordError);addEventListener('unhandledrejection',recordError);''' + literal + r'''
const params=new URLSearchParams(location.search);lang=params.get('language')||'ko';state=initial();state.screen='select';state.connected=true;
const variant=params.get('state')||'default';
if(variant==='expanded')state.expanded=new Set(categoryDefs.map(x=>x.key));
if(variant==='trial-unready'||variant==='trial-ready'){state.selected.add('trial');state.trial.ready=variant==='trial-ready'}
if(variant==='no-categories')state.selected.clear();
if(variant==='no-tables'||variant==='access-only-no-tables'){state.tables.clear();if(variant==='access-only-no-tables')state.selected=new Set(['access'])}
if(variant==='partial-tables')state.tables=new Set(['demo.customers']);
if(variant==='query-orders')tableQuery='orders';
if(variant==='query-none')tableQuery='missing-table';
if(variant==='manual-target-query'){state.maps['demo.orders']='archive.orders';tableQuery='archive'}
document.querySelector('.page').innerHTML=select();document.querySelector('.footer').innerHTML=footer();syncTableSelection();
function read(){
 const page=document.querySelector('.page'),origin=page.getBoundingClientRect();
 const box=e=>{const b=e.getBoundingClientRect();return{x:b.x-origin.x,y:b.y-origin.y,width:b.width,height:b.height}};
 const css=e=>{const s=getComputedStyle(e);return{display:s.display,color:s.color,background:s.backgroundColor,border:s.border,borderRadius:s.borderRadius,padding:s.padding,margin:s.margin,gap:s.gap,font:s.fontFamily,fontSize:s.fontSize,lineHeight:s.lineHeight,weight:s.fontWeight,spacing:s.letterSpacing,flex:s.flex,flexWrap:s.flexWrap,minWidth:s.minWidth,maxWidth:s.maxWidth,overflowX:s.overflowX,animationName:s.animationName,animationDuration:s.animationDuration}};
 const item=e=>e?{box:box(e),text:e.textContent,computed:css(e)}:null;
 const control=e=>({...item(e),name:e.getAttribute('aria-label'),id:e.id,action:e.dataset.action,checked:e.checked??null,mixed:e.indeterminate??null,disabled:e.disabled??null,placeholder:e.placeholder??null,value:e.value??null});
 const heading=page.querySelector('.page-heading'),section=page.querySelector('section.section'),shell=section.querySelector('.table-shell'),table=shell.querySelector('table'),footer=document.querySelector('.footer');
 const intrinsic={};for(const kind of ['min-content','max-content']){const clone=table.cloneNode(true);clone.style.cssText='position:absolute;visibility:hidden;width:'+kind+';max-width:none;top:0;left:0';document.body.append(clone);intrinsic[kind]={width:clone.getBoundingClientRect().width,columns:[...clone.querySelectorAll('thead th')].map(x=>x.getBoundingClientRect().width),rows:[...clone.querySelectorAll('tbody tr')].map(x=>x.getBoundingClientRect().height)};clone.remove()}
 return{id:params.get('id'),dpr:devicePixelRatio,viewportWidth:innerWidth,english:lang==='en',variant,root:item(page),content:item(document.querySelector('.content')),heading:item(heading),title:item(heading.querySelector('h1')),description:item(heading.querySelector('p')),scope:item(page.querySelector('.scope-heading')),categories:[...page.querySelectorAll('.category')].map(e=>({root:item(e),head:item(e.querySelector('.category-head')),toggle:control(e.querySelector('.category-toggle')),checkbox:control(e.querySelector('[data-category]')),body:item(e.querySelector('.category-body-wrap')),expanded:e.querySelector('.category-toggle').getAttribute('aria-expanded')})),preparation:item(page.querySelector('#trial-preparation')),section:item(section),sectionHeading:item(section.querySelector('.section-heading')),sectionTitle:item(section.querySelector('h2')),selectionCount:item(section.querySelector('#table-selection-count')),toolbar:item(section.querySelector('.table-toolbar')),search:control(section.querySelector('#table-search')),searchField:item(section.querySelector('.search-field')),clearSearch:control(section.querySelector('[data-action=clear-search]')),bulk:item(section.querySelector('.bulk-choice')),bulkCheckbox:control(section.querySelector('#table-all')),bulkLabel:item(section.querySelector('.bulk-choice span')),deselect:control(section.querySelector('[data-action=clear-tables]')),meta:item(section.querySelector('.table-meta')),searchCount:item(section.querySelector('#table-search-count')),searchHint:item(section.querySelector('.table-meta span:last-child')),tableShell:item(shell),table:item(table),headers:[...table.querySelectorAll('th')].map(item),rows:[...table.querySelectorAll('tbody tr')].map(e=>({root:item(e),cells:[...e.children].map(item),checkbox:e.querySelector('input')?control(e.querySelector('input')):null,change:e.querySelector('button')?control(e.querySelector('button')):null})),caption:item(section.querySelector('p.small')),footer:{root:item(footer),hint:item(footer.querySelector('.footer-hint')),back:control(footer.querySelector('[data-action=back]')),forward:control(footer.querySelector('[data-action=review]'))},intrinsic,structure:[...page.children].map(e=>({tag:e.tagName,className:e.className,id:e.id,childTags:[...e.children].map(x=>x.tagName)})),selection:{categories:[...state.selected],tables:[...state.tables],maps:state.maps,query:tableQuery,ready:state.trial.ready}}
}
'''
(out / 'selectionpage-original.css').write_bytes((r / 'docs/replica/source/original.css').read_bytes())
(out / 'selectionpage-inner.html').write_text('<!doctype html><meta charset="utf-8"><title>SelectionPage original iframe</title><link rel="stylesheet" href="selectionpage-original.css"><div class="shell"><div class="topbar"></div><aside class="rail"></aside><div class="workspace"><main class="content"><div class="page"></div></main><footer class="footer"></footer></div></div><script>'+script+'</script>')
outer = '''function recordError(e){fetch('/evidence/preflight-selectionpage-'+(new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({diagnostic:true,error:String(e.message||e.reason||e),stack:e.error?.stack||e.reason?.stack})})}addEventListener('error',recordError);addEventListener('unhandledrejection',recordError);const cases=CASES;for(const c of cases){const f=document.createElement('iframe');f.width=c.viewport;f.height=4000;f.src='selectionpage-inner.html?'+new URLSearchParams({language:c.language,state:c.state,id:c.id});f.style.display='none';document.getElementById('frames').append(f)}function stage(stage){const os=new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac';fetch('/evidence/preflight-selectionpage-'+os+'-control-ready.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stage,time:Date.now(),title:document.title})})}stage('bootstrap');async function record(){stage('record');const rows=[];for(const f of document.querySelectorAll('iframe')){f.style.display='block';stage('show-'+rows.length);if(!f.contentWindow.read)await new Promise(r=>f.addEventListener('load',r,{once:true}));stage('fonts-'+rows.length);await f.contentDocument.fonts.ready;stage('frames-'+rows.length);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));stage('animations-'+rows.length);await Promise.all(f.contentDocument.getAnimations().filter(a=>Number.isFinite(a.effect.getComputedTiming().endTime)).map(a=>a.finished.catch(()=>{})));stage('read-'+rows.length);rows.push(f.contentWindow.read());f.style.display='none'}document.querySelector('iframe').style.display='block';const os=new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac';const batch=new URLSearchParams(location.search).get('batch');const chunks=[rows.slice(0,18),rows.slice(18)];stage('post-size-'+JSON.stringify({total:new TextEncoder().encode(JSON.stringify({dpr:devicePixelRatio,rows})).length,chunks:chunks.map(x=>new TextEncoder().encode(JSON.stringify({dpr:devicePixelRatio,rows:x})).length)}));for(let i=0;i<chunks.length;i++){const body=JSON.stringify({dpr:devicePixelRatio,rows:chunks[i],batch,chunk:i,totalChunks:2});const response=await fetch('/evidence/preflight-selectionpage-'+(i?'b':'a')+'-'+os+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body});if(!response.ok)throw Error('Source chunk '+i+' rejected: HTTP'+response.status+' bytes='+new TextEncoder().encode(body).length)}document.getElementById('selectionpage-record').textContent='SelectionPage recorded'+rows.length}document.getElementById('selectionpage-record').onclick=record;if(new URLSearchParams(location.search).has('record'))addEventListener('load',record);'''.replace('CASES',json.dumps(cases))
(out / 'selectionpage.html').write_text('<!doctype html><meta charset="utf-8"><title>SelectionPage · original isolation</title><button id="selectionpage-record">Record SelectionPage</button><div id="frames"></div><script>'+outer+'</script>')
print(f'{len(cases)} literal Selection source cases prepared; no actual measurement executed')
